'use strict';
(()=>{
 const make=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 let state={favorites:[],playlists:[]},loaded=false;
 const key=i=>i.kind+'|'+i.id;
 function notice(message){let n=document.getElementById('personal-notice');if(!n){n=make('p',undefined,'personal-notice');n.id='personal-notice';n.setAttribute('role','status');document.body.append(n);}n.textContent=message;clearTimeout(n.timer);n.timer=setTimeout(()=>n.remove(),6000);}
 async function request(data){const r=await fetch('/api/library/personal',data?{method:'POST',headers:{'Content-Type':'application/json','X-Maha-Upload':'1'},body:JSON.stringify(data),cache:'no-store'}:{cache:'no-store'});const result=await r.json();if(!r.ok)throw Error(result.error||'Could not save your collection.');state=result;loaded=true;paint();window.dispatchEvent(new Event('maha-personal-change'));return state;}
 function has(item){return state.favorites.some(i=>key(i)===key(item));}
 function heartIcon(button){if(button.querySelector('svg'))return;const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d','M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z');svg.append(path);button.replaceChildren(svg);}
 function paint(){for(const n of document.querySelectorAll('[data-favorite-key]')){const saved=state.favorites.some(i=>key(i)===n.dataset.favoriteKey);heartIcon(n);n.setAttribute('aria-pressed',String(saved));n.setAttribute('aria-label',n._item.kind==='song'?(saved?'Unlike ':'Like ')+n._item.title:(saved?'Remove from':'Add to')+' favorites: '+n._item.title);n.title=n._item.kind==='song'?(saved?'Remove from Liked Songs':'Add to Liked Songs'):(saved?'Remove favorite':'Save favorite');n.disabled=!loaded;}}
 function button(item){const n=make('button',undefined,'favorite-heart');heartIcon(n);n.type='button';n._item=item;n.dataset.favoriteKey=key(item);n.disabled=!loaded;n.setAttribute('aria-pressed',String(has(item)));n.setAttribute('aria-label',(item.kind==='song'?(has(item)?'Unlike ':'Like '):'Favorite ')+item.title);n.title=item.kind==='song'?(has(item)?'Remove from Liked Songs':'Add to Liked Songs'):'Save favorite';n.onclick=async e=>{e.preventDefault();e.stopPropagation();n.disabled=true;try{await request({action:'favorite',item,saved:!has(item)});}catch(error){notice(error.message);if(loaded)await refresh().catch(()=>{});}finally{paint();}};return n;}
 async function refresh(){return request();}
 const ready=(window.MAHA_SESSION_READY||fetch('/api/library/session',{cache:'no-store'}).then(r=>r.json()).then(session=>{window.MAHA_SESSION=session;})).then(()=>{if(!window.MAHA_SESSION?.user)throw Error('Sign in to save favorites.');return refresh();}).catch(error=>{notice(error.message);return state;});
 function dialog(title){const d=make('dialog',undefined,'personal-dialog'),heading=make('h2',title),close=make('button','Close','text-btn');close.onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.append(close,heading);document.body.append(d);return d;}
 async function addToPlaylist(ids){await ready;if(!loaded)return notice('Please sign in to use playlists.');if(!ids.length)return notice('Select at least one recording.');const d=dialog('Add to playlist'),select=make('select'),label=make('label','Choose a playlist'),name=make('input'),create=make('button','Create playlist and add','action'),add=make('button','Add to playlist','action'),msg=make('p');select.setAttribute('aria-label','Choose a playlist');for(const p of state.playlists)select.add(new Option(p.name,p.id));label.append(select);name.placeholder='New playlist name';name.maxLength=100;name.setAttribute('aria-label','New playlist name');add.disabled=!state.playlists.length;async function save(data){add.disabled=create.disabled=true;try{await request(data);d.close();notice('Added to playlist.');}catch(e){msg.textContent=e.message;add.disabled=!state.playlists.length;create.disabled=false;}}add.onclick=()=>{const p=state.playlists.find(p=>p.id===select.value);if(p)save({action:'append',id:p.id,revision:p.revision,ids});};create.onclick=()=>save({action:'create',name:name.value,ids});if(state.playlists.length)d.append(label,add,make('hr'));else d.append(make('p','Create your first playlist to save these tracks.'));d.append(name,create,msg);d.showModal();}
 async function manager(options={}){await ready;if(!loaded)return notice('Please sign in to use playlists.');await refresh().catch(e=>notice(e.message));const d=dialog('Your playlists'),content=make('div'),msg=make('p');d.append(content,msg);let selected=options.liked?'liked-songs':null;async function change(data){try{await request(data);draw();}catch(e){msg.textContent=e.message;await refresh().catch(()=>{});draw();}}function play(p,shuffle,startId=null){if(window.MAHA_PLAY_PLAYLIST){window.MAHA_PLAY_PLAYLIST(p,shuffle,startId);d.close();}else location.href='music.html?playlist='+encodeURIComponent(p.id)+(shuffle?'&shuffle=1':'')+(startId?'&track='+encodeURIComponent(startId):'');}
 function draw(){content.replaceChildren();const create=make('button','New playlist','action');create.onclick=()=>{const name=prompt('Playlist name:');if(name!==null)change({action:'create',name,ids:[]});};content.append(create);if(!state.playlists.length)content.append(make('p','Create a playlist, then add songs or albums from Music.'));for(const p of [likedSongs(),...state.playlists]){const liked=p.id==='liked-songs';const section=make('section',undefined,'playlist-section'),open=make('button',p.name+' · '+p.tracks.length+' tracks','playlist-heading');open.onclick=()=>{selected=selected===p.id?null:p.id;draw();};section.append(open);if(selected===p.id){const actions=make('div',undefined,'personal-actions'),start=make('button','Play','action'),shuffle=make('button','Shuffle','action'),rename=make('button','Rename'),remove=make('button','Delete playlist');start.disabled=shuffle.disabled=!p.tracks.some(t=>t.available);start.onclick=()=>play(p,false);shuffle.onclick=()=>play(p,true);rename.onclick=()=>{const name=prompt('Playlist name:',p.name);if(name!==null)change({action:'rename',id:p.id,revision:p.revision,name});};remove.onclick=()=>{if(confirm('Delete playlist “'+p.name+'”? Music files will stay in the library.'))change({action:'delete',id:p.id,revision:p.revision});};actions.append(start,shuffle);if(!liked)actions.append(rename,remove);section.append(actions);const list=make('ol');for(const [index,t] of p.tracks.entries()){const row=make('li'),title=make('span',t.title+' — '+t.artist+(t.available?'':' · Unavailable')),up=make('button','↑'),down=make('button','↓'),del=make('button','Remove');up.setAttribute('aria-label','Move '+t.title+' up');down.setAttribute('aria-label','Move '+t.title+' down');up.disabled=index===0;down.disabled=index===p.tracks.length-1;function move(delta){const ids=p.tracks.map(t=>t.id);[ids[index],ids[index+delta]]=[ids[index+delta],ids[index]];change({action:'reorder',id:p.id,revision:p.revision,ids});}up.onclick=()=>move(-1);down.onclick=()=>move(1);del.onclick=()=>liked?change({action:'favorite',item:{kind:'song',id:t.id},saved:false}):change({action:'reorder',id:p.id,revision:p.revision,ids:p.tracks.filter(x=>x.id!==t.id).map(t=>t.id)});if(liked){up.hidden=down.hidden=true;del.textContent='Unlike';}const playTrack=make('button','▶ Play');playTrack.disabled=!t.available;playTrack.onclick=()=>play(p,false,t.id);row.append(title,playTrack,up,down,del);list.append(row);}section.append(list);}content.append(section);}}
 draw();d.showModal();}
 function saveButton(item){const n=make('button',has(item)?'Remove favorite':'Save favorite','text-btn book-edit');n.type='button';n.onclick=async event=>{event.preventDefault();event.stopPropagation();n.disabled=true;try{await request({action:'favorite',item,saved:!has(item)});n.textContent=has(item)?'Remove favorite':'Save favorite';}catch(e){notice(e.message);}finally{n.disabled=false;}};return n;}
 function likedSongs(){return {id:'liked-songs',name:'Liked Songs',tracks:state.favorites.filter(i=>i.kind==='song').map(i=>({id:i.id,title:i.title,artist:i.subtitle,available:i.available!==false}))};}
 window.MAHA_PERSONAL={saveButton,likedSongs,ready,get state(){return state;},has,button,refresh,addToPlaylist,manager,notice};
 window.addEventListener('focus',()=>{if(loaded)refresh().catch(()=>{});});
 function userLinks(){const actions=document.querySelector('.maha-session-actions');if(!actions||!window.MAHA_SESSION?.user||actions.querySelector('[data-personal-user-links]'))return;const links=make('span',undefined,'personal-user-links');links.dataset.personalUserLinks='';const liked=make('button','Liked Songs'),playlists=make('button','Manage playlists');liked.type=playlists.type='button';liked.onclick=()=>manager({liked:true});playlists.onclick=()=>manager();links.append(liked,playlists);actions.prepend(links);}
 document.addEventListener('maha-session',userLinks);ready.then(userLinks);
 document.addEventListener('DOMContentLoaded',()=>{userLinks();const nav=document.querySelector('header nav');if(nav&&!nav.querySelector('[href="favorites.html"]')){const a=make('a','Favorites');a.href='favorites.html';nav.append(a);}});

 document.addEventListener('DOMContentLoaded',()=>{const header=document.querySelector('header'),title=document.getElementById('title');if(!header||!title)return;const params=new URLSearchParams(location.search);let heart=null;function show(item){if(!heart){heart=button(item);header.append(heart);}else{heart._item=item;heart.dataset.favoriteKey=key(item);}paint();}if(location.pathname.endsWith('/reader.html')&&params.get('id')){const update=()=>show({kind:'book',id:params.get('id'),title:title.textContent,subtitle:document.getElementById('author')?.textContent||'',url:'reader.html?id='+encodeURIComponent(params.get('id'))});new MutationObserver(update).observe(title,{childList:true,subtree:true,characterData:true});update();}if(location.pathname.endsWith('/archive-reader.html')){const frame=document.getElementById('content');const update=()=>{try{const u=new URL(frame.contentWindow.location.href);if(u.origin!==location.origin||!/^\/(?:kiwix\/content\/|archive\/askaprepper\/)/.test(u.pathname))return;const local=u.pathname+u.search+u.hash,name=frame.contentDocument.title||title.textContent;show({kind:u.pathname.startsWith('/kiwix/')?'knowledge':'site',id:local,title:name,subtitle:'Saved reading page',url:'archive-reader.html?url='+encodeURIComponent(local)+'&title='+encodeURIComponent(name)});}catch{}};frame.addEventListener('load',update);update();}});
 // Deferred scripts may run after the DOM is parsed but before DOMContentLoaded.
})();
